import{_ as r,l as o,o as a,c as l,v as i,p as f,x as t,d as n,i as d,S as p}from"./chunks/framework.InCnrqk-.js";const j=JSON.parse('{"title":"jiffies","description":"","frontmatter":{"title":"jiffies","date":"2026-09-08T00:00:00.000Z","section":"cs"},"headers":[],"relativePath":"cs/jiffies.md","filePath":"cs/jiffies.md","lastUpdated":1789023840000}'),c={name:"cs/jiffies.md"};function h(m,e,_,E,u,A){const s=o("Mermaid");return a(),l("div",null,[e[1]||(e[1]=i('<h1 id="jiffies" tabindex="-1">jiffies <a class="header-anchor" href="#jiffies" aria-label="Permalink to &quot;jiffies&quot;">​</a></h1><div class="epigraph"><p>内核用滴答中断累加一个计数器；HZ 次每秒，超时、调度记账和时间片都曾以它为粗粒度时钟。</p><footer>—— 据 Bovet and Cesati；Love, Linux Kernel Development；Tanenbaum MOS 整理</footer></div><p><a href="/cs/io-uring">上一课</a>的等待可以带超时，却还没有「内核如何数时间」。<a href="/cs/timeslice-cfs">时间片</a> 已用时间记账，当时把时钟当黑盒。<a href="/cs/interrupt-bottom-half">中断下半部</a> 假定定时器 IRQ 会来。缺口是 <strong>jiffies</strong>：滴答、HZ、回绕、以及它不够精细——留给下一课 hrtimer。</p><h2 id="问题" tabindex="-1">问题 <a class="header-anchor" href="#问题" aria-label="Permalink to &quot;问题&quot;">​</a></h2><p>若每次睡眠都读 CPU 周期计数器，旧机器没有或不同核会漂。经典 Unix：编程间隔定时器，HZ（如 100 或 250）次每秒加一。超时时刻记成「未来的 jiffies」。缺口：谁在 IRQ 里加一、32 位回绕如何比较、用户 <code>sleep</code> 的分辨率不能高于滴答。动态 HZ 与无滴答（tickless）是实现，对象仍是「软件时间基」。</p><p>本课不把每架构的时钟事件设备编程写完。</p><p><span class="marginnote">比较用有符号差处理回绕。jiffies 不是 UTC；墙上时钟是另一套（xtime），可被 NTP 调。本课只钉单调滴答。</span></p><h2 id="方法" tabindex="-1">方法 <a class="header-anchor" href="#方法" aria-label="Permalink to &quot;方法&quot;">​</a></h2><p>时钟 IRQ → 更新 jiffies → 检查定时器轮（timer wheel）上到期的软件定时器 → 可能标记调度。进程在内核睡眠时把「目标 jiffies」挂进等待队列。超时与 <a href="/cs/select-poll">select</a> 共用这条。不要把 TSC 校准全文展开；jiffies 可以由更高精度时钟累加出来。</p>',9)),(a(),f(p,null,{default:t(()=>[d(s,{id:"mermaid-25",class:"mermaid",graph:"flowchart%20TD%0A%20%20IRQ%5B%22%E6%BB%B4%E7%AD%94%E4%B8%AD%E6%96%AD%22%5D%20--%3E%20INC%5B%22jiffies%2B%2B%22%5D%0A%20%20INC%20--%3E%20WHEEL%5B%22%E5%AE%9A%E6%97%B6%E5%99%A8%E8%BD%AE%E5%88%B0%E6%9C%9F%22%5D%0A%20%20WHEEL%20--%3E%20WAKE%5B%22%E5%94%A4%E9%86%92%E7%9D%A1%E7%9C%A0%E8%80%85%20%2F%20%E8%AE%B0%E8%B4%A6%22%5D%0A"})]),fallback:t(()=>[...e[0]||(e[0]=[n(" Loading... ",-1)])]),_:1})),e[2]||(e[2]=i('<h2 id="机制" tabindex="-1">机制 <a class="header-anchor" href="#机制" aria-label="Permalink to &quot;机制&quot;">​</a></h2><p>jiffies 把时间变成整数，让 OS 能在没有用户态时钟的情况下做公平调度与 I/O 超时。分辨率与延迟下限被 HZ 绑住：HZ=100 则 10ms 粒度。这解释了为何管道超时与 nanosleep 在旧内核上不准。下一课用时钟事件设备实现更高分辨率，而不必把 HZ 拉到十万。</p><p>与组成课的时钟域不同：这里是软件计数，不是 PLL。</p><h2 id="边界" tabindex="-1">边界 <a class="header-anchor" href="#边界" aria-label="Permalink to &quot;边界&quot;">​</a></h2><p>本课不引入 CLOCK_MONOTONIC 的全部 POSIX 钟。不保证虚拟机里滴答与真时间 1:1（偷时间）。下一课：纳秒级期限与红黑树定时器。</p><p>后课默认：粗超时可用 jiffies。细期限与高精度时钟事件，下一课 hrtimer。</p><h2 id="小结" tabindex="-1">小结 <a class="header-anchor" href="#小结" aria-label="Permalink to &quot;小结&quot;">​</a></h2><ul><li>jiffies 由滴答累加，驱动 timer wheel 与记账。</li><li>分辨率受 HZ 限制，回绕用有符号差比较。</li><li>高精度定时是 hrtimer 的缺口。</li><li>出处：Bovet and Cesati, <em>ULK</em>；Love, <em>LKD</em>；Tanenbaum <em>MOS</em>。</li></ul>',8))])}const B=r(c,[["render",h]]);export{j as __pageData,B as default};
